import{_ as e,r as n,o,c,e as a,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Коллекции - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Доступные методы","slug":"доступные-методы","link":"#доступные-методы","children":[]},{"level":2,"title":"Пользовательские коллекции","slug":"пользовательские-коллекции","link":"#пользовательские-коллекции","children":[]}],"relativePath":"3.x/ru/extend/database/collection.md","filePath":"3.x/ru/extend/database/collection.md"}'),i={name:"3.x/ru/extend/database/collection.md"};function r(k,s,d,g,v,m){const p=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(p),s[0]||(s[0]=l("h1",null,"Коллекции",-1)),a(t),s[1]||(s[1]=u(`<p>Все наборы результатов с множественными записями, возвращаемые моделью, являются экземплярами объекта <code>October\\Rain\\Database\\Collection</code>, включая результаты, полученные через метод <code>get</code> или доступ через связь. Объект <code>Collection</code> расширяет <a href="./../services/collections.html">базовую коллекцию</a>, поэтому он естественным образом наследует десятки методов для удобной работы с базовым массивом моделей.</p><p>Все коллекции также служат итераторами, позволяя вам перебирать их, как простые PHP-массивы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Однако коллекции гораздо мощнее массивов и предоставляют различные операции map / reduce с использованием интуитивного интерфейса. Например, давайте отфильтруем все активные модели и соберём имя для каждого отфильтрованного пользователя.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$names</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">is_active</span> <span class="token operator">===</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Хотя большинство методов коллекции моделей возвращают новый экземпляр коллекции <code>Eloquent</code>, методы <code>pluck</code>, <code>keys</code>, <code>zip</code>, <code>collapse</code>, <code>flatten</code> и <code>flip</code> возвращают экземпляр базовой коллекции. Аналогично, если операция <code>map</code> возвращает коллекцию, не содержащую моделей, она автоматически приводится к базовой коллекции.</p></div><h2 id="доступные-методы"><a href="#доступные-методы" class="header-anchor">#</a> Доступные методы</h2><p>Все коллекции моделей расширяют базовый объект коллекции; поэтому они наследуют все мощные методы, предоставляемые базовым классом коллекции.</p><p>Кроме того, класс <code>October\\Rain\\Database\\Collection</code> предоставляет расширенный набор методов для управления вашими коллекциями моделей. Большинство методов возвращают экземпляры <code>October\\Rain\\Database\\Collection</code>; однако некоторые методы возвращают экземпляр базовой <code>Illuminate\\Support\\Collection</code>.</p><p><strong>contains($key, $operator = null, $value = null)</strong></p><p>Метод <code>contains</code> может использоваться для определения, содержится ли данный экземпляр модели в коллекции. Этот метод принимает первичный ключ или экземпляр модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">contains</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">contains</span><span class="token punctuation">(</span><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>diff($items)</strong></p><p>Метод <code>diff</code> возвращает все модели, которые отсутствуют в данной коллекции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">App<span class="token punctuation">\\</span>User</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">diff</span><span class="token punctuation">(</span><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>except($keys)</strong></p><p>Метод <code>except</code> возвращает все модели, которые не имеют указанных первичных ключей:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">except</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>find($key)</strong></p><p>Метод <code>find</code> находит модель с указанным первичным ключом. Если <code>$key</code> является экземпляром модели, <code>find</code> попытается вернуть модель, совпадающую по первичному ключу. Если <code>$key</code> является массивом ключей, find вернёт все модели, которые совпадают с <code>$keys</code>, используя <code>whereIn()</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>fresh($with = [])</strong></p><p>Метод <code>fresh</code> получает свежий экземпляр каждой модели в коллекции из базы данных. Кроме того, любые указанные связи будут жадно загружены:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">fresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">fresh</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>intersect($items)</strong></p><p>Метод <code>intersect</code> возвращает все модели, которые также присутствуют в данной коллекции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">App<span class="token punctuation">\\</span>User</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">intersect</span><span class="token punctuation">(</span><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>load($relations)</strong></p><p>Метод <code>load</code> жадно загружает указанные связи для всех моделей в коллекции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments.author&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>loadMissing($relations)</strong></p><p>Метод <code>loadMissing</code> жадно загружает указанные связи для всех моделей в коллекции, если связи ещё не загружены:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">loadMissing</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">loadMissing</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments.author&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>modelKeys()</strong></p><p>Метод <code>modelKeys</code> возвращает первичные ключи для всех моделей в коллекции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">modelKeys</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// [1, 2, 3, 4, 5]</span>
</code></pre></div><p><strong>makeVisible($attributes)</strong></p><p>Метод <code>makeVisible</code> делает видимыми атрибуты, которые обычно являются «скрытыми» в каждой модели коллекции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">makeVisible</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;address&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;phone_number&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>makeHidden($attributes)</strong></p><p>Метод <code>makeHidden</code> скрывает атрибуты, которые обычно являются «видимыми» в каждой модели коллекции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">makeHidden</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;address&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;phone_number&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>only($keys)</strong></p><p>Метод <code>only</code> возвращает все модели, которые имеют указанные первичные ключи:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">only</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>unique($key = null, $strict = false)</strong></p><p>Метод <code>unique</code> возвращает все уникальные модели в коллекции. Любые модели того же типа с тем же первичным ключом, что и другая модель в коллекции, удаляются.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="пользовательские-коллекции"><a href="#пользовательские-коллекции" class="header-anchor">#</a> Пользовательские коллекции</h2><p>Если вам нужно использовать пользовательский объект <code>Collection</code> с вашими собственными методами расширения, вы можете переопределить метод <code>newCollection</code> в вашей модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * Create a new Collection instance.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">newCollection</span><span class="token punctuation">(</span><span class="token keyword type-hint">array</span> <span class="token variable">$models</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">CustomCollection</span><span class="token punctuation">(</span><span class="token variable">$models</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>После определения метода <code>newCollection</code> вы будете получать экземпляр вашей пользовательской коллекции каждый раз, когда модель возвращает экземпляр <code>Collection</code>. Если вы хотите использовать пользовательскую коллекцию для каждой модели в вашем плагине или приложении, вы должны переопределить метод <code>newCollection</code> в базовом классе модели, от которого наследуются все ваши модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Collection</span> <span class="token keyword">as</span> CollectionBase<span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">CustomCollection</span> <span class="token keyword">extends</span> <span class="token class-name">CollectionBase</span>
<span class="token punctuation">{</span>
<span class="token punctuation">}</span>
</code></pre></div>`,53))])}const h=e(i,[["render",r]]);export{f as __pageData,h as default};
